// NEX Food Knowledge · structured knowledge for images NEX has learned.
//
// This is the KNOWLEDGE LAYER that NEX brain will query when a user
// asks about a dish, ingredient, cuisine, or category. Explicitly NOT
// just descriptions — every record carries:
//   · what NEX is CERTAIN of (visible objects + attributes)
//   · what NEX is UNCERTAIN of (guesses that should not be reported
//     as facts — e.g. "possibly mochi" not "mochi")
//   · CONFIDENCE bands per identification
//   · EVIDENCE the identification was based on
//   · RELATIONSHIPS between items (syrup → ice cream · mango → bowl)
//   · IMAGE PROVENANCE (per Owner-Provenanced Pricing doctrine — image
//     provenance chain is SEPARATE from business-data provenance chain)
//
// Philip 2026-08-21 (verbatim guidance):
//   "NEX should not turn visual guesses into facts."
//   "Don't just describe the image — turn the description into
//    structured food knowledge with confidence and relationships."
//
// PIPELINE INTENT (Priority 4+ when NEX food brain lands):
//   IMAGE → OBJECT DETECTION → FOOD IDENTIFICATION → INGREDIENT/
//   ATTRIBUTE EXTRACTION → RELATIONSHIP EXTRACTION → CONFIDENCE +
//   UNCERTAINTY → NEX KNOWLEDGE GRAPH → USER ANSWER
//
// For V1 this file stores the CURATED knowledge for images Philip has
// personally reviewed + approved. When the vision pipeline goes live,
// it will produce records of this same shape automatically.

import type { FoodCategory } from "./foodListings";

// ── Types ──────────────────────────────────────────────────

export type ConfidenceBand = "very-high" | "high" | "medium" | "low";

/** A single identified item in an image. `confidence` and `evidence`
 *  are mandatory so downstream code / brain queries can distinguish
 *  certain facts from probable guesses. */
export type FoodItem = {
  name: string;                       // NEX's identification of the item
  confidence: ConfidenceBand;
  evidence: string;                   // WHY NEX believes this — the
                                      // visual/context basis for the ID
  alternativeIdentity?: string;       // "possibly X" · used when confidence < high
  quantity?: string;                  // "several" · "one" · "assorted"
};

/** An ingredient probably present in the food. */
export type Ingredient = {
  name: string;
  confidence: ConfidenceBand;
};

/** Visual attribute (colour, texture, temperature signal, etc.). */
export type FoodAttribute = {
  facet: "colour" | "texture" | "temperature" | "flavour" | "portion";
  value: string;
  confidence: ConfidenceBand;
};

/** Relationship between two visible items in the image. */
export type FoodRelationship = {
  subject: string;
  relation: "on" | "beside" | "topped-with" | "served-with" | "inside" | "drizzled-on";
  object: string;
};

export type MealType = "breakfast" | "lunch" | "dinner" | "snack" | "dessert" | "drink";
export type ServingStyle = "individual" | "sharing-platter" | "takeaway" | "buffet";

/** Image provenance chain — SEPARATE from business-data provenance
 *  per pinned `project_nex_business_acquisition_pipeline`. */
export type FoodImageProvenance = {
  source: "nex_curated_v1" | "owner_uploaded" | "owner_authorised";
  approved: boolean;
  approvedByNote?: string;            // e.g. "Philip 2026-08-21"
  updatedAt: string;                  // ISO
};

/** The full knowledge record for a food image. */
export type FoodKnowledgeRecord = {
  id: string;                         // internal · never exposed
  publicKnowledgeRef: string;         // #FK-YOG-001 style stable ref
  imageUrl: string;                   // full public URL
  imageKitPath?: string;              // useful for future CDN transforms
  categorySlug: FoodCategory;         // maps into FoodListings taxonomy
  cuisine?: string;                   // "Japanese" · "Chinese" · "Indonesian" etc.
  primaryDish?: string;               // shortest human name for the dish
  visibleItems: readonly FoodItem[];
  ingredients?: readonly Ingredient[];
  accompaniments?: readonly string[]; // wasabi · pickled ginger · sesame etc.
  attributes?: readonly FoodAttribute[];
  preparation?: readonly string[];    // "scooped" · "drizzled" · "grilled"
  presentationStyle?: string;         // "premium platter" · "casual takeaway"
  mealType?: readonly MealType[];
  servingStyle?: ServingStyle;
  dietaryTags?: readonly string[];    // "seafood-based" · "vegetarian-option" · "spicy"
  directoryTags: readonly string[];   // free-text tags for search retrieval
  humanDescription: string;           // shown to users — one paragraph
  brainDescription: string;           // richer, brain-friendly recap
  imageProvenance: FoodImageProvenance;
  confidenceOverall: ConfidenceBand;
  uncertainty?: readonly string[];    // "exact fish variety not confirmed" etc.
                                      // NEX MUST NOT claim these as fact
  relationships?: readonly FoodRelationship[];
  createdAt: string;                  // ISO · when the record was written
};

