// ── Retrieval helpers (used by NEX brain when it lands · Priority 4+) ──

/** Look up a knowledge record by its stable public reference. */
export function knowledgeByRef(ref: string): FoodKnowledgeRecord | undefined {
  return FOOD_KNOWLEDGE.find((r) => r.publicKnowledgeRef === ref);
}

/** All knowledge records for a given category. */
export function knowledgeByCategory(category: FoodCategory): FoodKnowledgeRecord[] {
  return FOOD_KNOWLEDGE.filter((r) => r.categorySlug === category);
}

/**
 * Simple client-side search across directoryTags + names + descriptions.
 * The real NEX brain retrieval will use embeddings + a knowledge graph;
 * this substring search is a V1 stand-in so the Food UI has SOMETHING
 * to query before Priority 4+ backend lands.
 *
 * Only returns records with confidenceOverall >= "medium" — low-confidence
 * (pending description) records are excluded from search results to
 * prevent NEX from surfacing them as knowledge.
 */
export function searchKnowledge(query: string): FoodKnowledgeRecord[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return FOOD_KNOWLEDGE.filter((r) => {
    if (r.confidenceOverall === "low") return false;
    const hay = [
      r.primaryDish ?? "",
      r.cuisine ?? "",
      r.humanDescription,
      r.brainDescription,
      ...r.directoryTags,
      ...r.visibleItems.map((v) => v.name),
      ...(r.ingredients?.map((i) => i.name) ?? []),
    ].join(" · ").toLowerCase();
    return hay.includes(q);
  });
}

